import java.util.ArrayList;
import java.util.Collections;
import java.util.Random;
import java.util.Scanner;

public class Main {
    static GameState state = new GameState();
    static boolean quiet = false;
    static Scanner scanner = new Scanner(System.in);

    // persistence tracking — set per session/round
    static GameSessionEntity currentSession = null;
    static int currentRoundNumber = 0;

    public static void main(String[] args) {
        int bots = 3;
        int games = 1;
        boolean human = false;
        boolean showStats = false;
        long seed = System.currentTimeMillis();

        for (int i = 0; i < args.length; i++) {
            if (args[i].equals("--bots") && i + 1 < args.length) {
                bots = Integer.parseInt(args[++i]);
            } else if (args[i].equals("--games") && i + 1 < args.length) {
                games = Integer.parseInt(args[++i]);
            } else if (args[i].equals("--human")) {
                human = true;
            } else if (args[i].equals("--quiet")) {
                quiet = true;
            } else if (args[i].equals("--seed") && i + 1 < args.length) {
                seed = Long.parseLong(args[++i]);
            } else if (args[i].equals("--stats")) {
                showStats = true;
            } else if (args[i].equals("--self-test")) {
                selfTest();
                return;
            } else if (args[i].equals("--help")) {
                System.out.println("Usage: scripts/run.sh [--bots N] [--games N] [--human] [--quiet] [--seed N] [--stats]");
                return;
            }
        }

        // suppress verbose Hibernate startup noise so the CLI stays readable
        java.util.logging.Logger.getLogger("org.hibernate").setLevel(java.util.logging.Level.WARNING);
        PersistenceService.init("uno-pu");

        if (showStats) {
            PersistenceService.printStats();
            PersistenceService.close();
            return;
        }

        state.random = new Random(seed);
        setupPlayers(bots, human);

        if (state.players.size() < 2 || state.players.size() > 4) {
            System.out.println("UNO needs 2 to 4 players.");
            PersistenceService.close();
            return;
        }

        currentSession = PersistenceService.startSession(state.players);

        for (int g = 1; g <= games; g++) {
            currentRoundNumber = g;
            Display.gameStart(g);
            GameLog.gameStart(g, state.players.size());
            playGame();
        }

        PersistenceService.finishSession(currentSession, state.players, state.scores);
        Display.finalScores(state.players, state.scores);
        GameLog.gameEnd();
        PersistenceService.close();
    }

    static void setupPlayers(int bots, boolean human) {
        state.players.clear();
        if (human) {
            state.players.add(new Player("You", true));
        }
        for (int i = 1; i <= bots; i++) {
            state.players.add(new Player("Bot" + i, false));
        }
    }

    static void playGame() {
        buildDeck();
        Collections.shuffle(state.deck, state.random);
        state.discard.clear();
        dealHands();
        state.upCard = draw();
        while (state.upCard.startsWith("W")) {
            state.discard.add(state.upCard);
            state.upCard = draw();
        }
        state.calledColor = "";
        state.direction = 1;
        state.currentPlayer = state.random.nextInt(state.players.size());

        int guard = 0;
        while (guard < 3000) {
            guard++;
            Player current = state.players.get(state.currentPlayer);

            Display.turnState(state.upCard, state.calledColor, current.name, current.hand);
            GameLog.playerTurn(current.name, state.upCard, state.calledColor);

            int chosen = -1;
            if (current.isHuman) {
                chosen = askHuman(current.hand);
            } else {
                chosen = chooseBotCard(current.hand);
            }

            if (chosen == -1) {
                chosen = handleDraw(current.hand, current.name);
            }

            if (chosen >= 0) {
                if (chosen >= current.hand.size()) {
                    Display.penaltyCard(current.name);
                    current.hand.add(draw());
                    next();
                    continue;
                }

                String card = current.hand.get(chosen);

                if (!isLegal(card, state.upCard, state.calledColor)) {
                    Display.illegalCard(current.name, card);
                    current.hand.add(draw());
                    next();
                    continue;
                }

                current.hand.remove(chosen);
                state.discard.add(state.upCard);
                state.upCard = card;
                state.calledColor = "";
                Display.playerPlays(current.name, card);
                GameLog.cardPlayed(current.name, card);

                if (card.equals("W") || card.equals("W4")) {
                    if (current.isHuman) {
                        state.calledColor = askColor();
                    } else {
                        state.calledColor = chooseBotColor(current.hand);
                    }
                    Display.playerCallsColor(current.name, state.calledColor);
                }

                if (current.hand.size() == 1) {
                    Display.uno(current.name);
                }

                if (current.hand.size() == 0) {
                    scoreRound(current.name);
                    return;
                }

                applyCardEffect(card);
            } else {
                next();
            }
        }
        Display.safetyLimit();
    }

    // draws a card for the current player and returns the index to play it,
    // or -1 if the drawn card isn't legal (or human chose not to play it)
    static int handleDraw(ArrayList<String> hand, String name) {
        String drawn = draw();
        hand.add(drawn);
        Display.playerDraws(name, drawn);
        GameLog.cardDrawn(name, drawn);
        if (isLegal(drawn, state.upCard, state.calledColor)) {
            if (!state.players.get(state.currentPlayer).isHuman) {
                return hand.size() - 1;
            } else {
                System.out.print("Play drawn card " + drawn + "? y/n: ");
                String answer = scanner.nextLine();
                if (answer.equalsIgnoreCase("y") || answer.equalsIgnoreCase("yes")) {
                    return hand.size() - 1;
                }
            }
        }
        return -1;
    }

    static void dealHands() {
        for (int i = 0; i < state.players.size(); i++) {
            state.players.get(i).hand.clear();
            for (int j = 0; j < 7; j++) {
                state.players.get(i).hand.add(draw());
            }
        }
    }

    static void buildDeck() {
        state.deck.clear();
        String[] colors = {"R", "Y", "G", "B"};
        for (int c = 0; c < colors.length; c++) {
            state.deck.add(colors[c] + "0");
            for (int n = 1; n <= 9; n++) {
                state.deck.add(colors[c] + n);
                state.deck.add(colors[c] + n);
            }
            state.deck.add(colors[c] + "S");
            state.deck.add(colors[c] + "S");
            state.deck.add(colors[c] + "R");
            state.deck.add(colors[c] + "R");
            state.deck.add(colors[c] + "+2");
            state.deck.add(colors[c] + "+2");
        }
        for (int i = 0; i < 4; i++) {
            state.deck.add("W");
            state.deck.add("W4");
        }
    }

    static String draw() {
        if (state.deck.size() == 0) {
            state.deck.addAll(state.discard);
            state.discard.clear();
            Collections.shuffle(state.deck, state.random);
        }
        if (state.deck.size() == 0) {
            return "W";
        }
        return state.deck.remove(0);
    }

    static void scoreRound(String winnerName) {
        int points = 0;
        for (int i = 0; i < state.players.size(); i++) {
            if (i != state.currentPlayer) {
                for (int j = 0; j < state.players.get(i).hand.size(); j++) {
                    points += points(state.players.get(i).hand.get(j));
                }
            }
        }
        state.scores[state.currentPlayer] += points;
        Display.winsRound(winnerName, points);
        GameLog.roundEnd(winnerName, points);
        if (currentSession != null) {
            PersistenceService.addRound(currentSession, currentRoundNumber, winnerName, points);
        }
    }

    static void applyCardEffect(String card) {
        switch (rank(card)) {
            case "SKIP":
                next();
                next();
                break;
            case "REVERSE":
                state.direction = state.direction * -1;
                if (state.players.size() == 2) {
                    next();
                    next();
                } else {
                    next();
                }
                break;
            case "DRAW_TWO":
                next();
                state.players.get(state.currentPlayer).hand.add(draw());
                state.players.get(state.currentPlayer).hand.add(draw());
                Display.drawsTwo(state.players.get(state.currentPlayer).name);
                next();
                break;
            case "WILD_DRAW_FOUR":
                next();
                for (int i = 0; i < 4; i++) {
                    state.players.get(state.currentPlayer).hand.add(draw());
                }
                Display.drawsFour(state.players.get(state.currentPlayer).name);
                next();
                break;
            default:
                next();
                break;
        }
    }

    static int chooseBotCard(ArrayList<String> hand) {
        for (int i = 0; i < hand.size(); i++) {
            if (rank(hand.get(i)).equals("DRAW_TWO") && isLegal(hand.get(i), state.upCard, state.calledColor)) {
                return i;
            }
        }
        for (int i = 0; i < hand.size(); i++) {
            if (rank(hand.get(i)).equals("SKIP") && isLegal(hand.get(i), state.upCard, state.calledColor)) {
                return i;
            }
        }
        for (int i = 0; i < hand.size(); i++) {
            if (rank(hand.get(i)).equals("NUMBER") && isLegal(hand.get(i), state.upCard, state.calledColor)) {
                return i;
            }
        }
        for (int i = 0; i < hand.size(); i++) {
            if (hand.get(i).startsWith("W")) {
                return i;
            }
        }
        return -1;
    }

    // just parsing — no legality check here, returns -1 for draw, -2 if not understood
    static int parseCardInput(String input, ArrayList<String> hand) {
        if (input.equals("DRAW")) return -1;
        try {
            int index = Integer.parseInt(input);
            if (index >= 0 && index < hand.size()) return index;
        } catch (Exception ignored) {
        }
        for (int i = 0; i < hand.size(); i++) {
            if (hand.get(i).equals(input)) return i;
        }
        return -2;
    }

    static int askHuman(ArrayList<String> hand) {
        while (true) {
            System.out.print("Choose card index/code or draw: ");
            String input = scanner.nextLine().trim().toUpperCase();
            int idx = parseCardInput(input, hand);
            if (idx == -1) return -1;
            if (idx == -2) {
                System.out.println("Card not found.");
                GameLog.invalidInput("You", "card-not-found:" + input);
                continue;
            }
            if (!isLegal(hand.get(idx), state.upCard, state.calledColor)) {
                System.out.println("That card is not legal.");
                GameLog.invalidInput("You", "illegal-card:" + hand.get(idx));
                continue;
            }
            return idx;
        }
    }

    static String askColor() {
        while (true) {
            System.out.print("Call color R/Y/G/B: ");
            String input = scanner.nextLine().trim().toUpperCase();
            if (input.equals("R")) return "R";
            if (input.equals("Y")) return "Y";
            if (input.equals("G")) return "G";
            if (input.equals("B")) return "B";
            System.out.println("Bad color.");
        }
    }

    static String chooseBotColor(ArrayList<String> hand) {
        int r = 0, y = 0, g = 0, b = 0;
        for (int i = 0; i < hand.size(); i++) {
            String c = color(hand.get(i));
            if (c.equals("R")) r++;
            else if (c.equals("Y")) y++;
            else if (c.equals("G")) g++;
            else if (c.equals("B")) b++;
        }
        if (r >= y && r >= g && r >= b) return "R";
        if (y >= r && y >= g && y >= b) return "Y";
        if (g >= r && g >= y && g >= b) return "G";
        return "B";
    }

    // quick helpers so i don't have to write new Card(...) everywhere
    static boolean isLegal(String card, String up, String call) { return new Card(card).isLegalOn(up, call); }
    static String color(String card)  { return new Card(card).color(); }
    static String rank(String card)   { return new Card(card).rank(); }
    static int    number(String card) { return new Card(card).number(); }
    static int    points(String card) { return new Card(card).points(); }

    static void next() {
        state.currentPlayer += state.direction;
        if (state.currentPlayer >= state.players.size()) state.currentPlayer = 0;
        if (state.currentPlayer < 0) state.currentPlayer = state.players.size() - 1;
    }

    static String join(ArrayList<String> cards) {
        String out = "";
        for (int i = 0; i < cards.size(); i++) {
            out += i + ":" + cards.get(i);
            if (i < cards.size() - 1) out += " ";
        }
        return out;
    }

    static void selfTest() {
        int passed = 0;
        if (color("R5").equals("R")) passed++; else fail("color R5");
        if (rank("G+2").equals("DRAW_TWO")) passed++; else fail("rank +2");
        if (points("W4") == 50) passed++; else fail("wild points");
        if (isLegal("R2", "R9", "")) passed++; else fail("same color");
        if (isLegal("G9", "R9", "")) passed++; else fail("same number");
        if (isLegal("B3", "W", "B")) passed++; else fail("called color");
        if (!isLegal("B3", "R9", "")) passed++; else fail("illegal mismatch");

        ArrayList<String> h = new ArrayList<>();
        h.add("B3"); h.add("R4"); h.add("W");
        state.upCard = "R9";
        state.calledColor = "";
        if (chooseBotCard(h) == 1) passed++; else fail("bot normal before wild");

        ArrayList<String> h2 = new ArrayList<>();
        h2.add("B1"); h2.add("B2"); h2.add("R3");
        if (chooseBotColor(h2).equals("B")) passed++; else fail("bot color");

        System.out.println("Passed " + passed + " characterization checks.");
    }

    static void fail(String name) {
        throw new RuntimeException("Failed: " + name);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Random;
import java.util.Scanner;

public class Main {
    static GameState state = new GameState();
    static boolean quiet = false;
    static Scanner scanner = new Scanner(System.in);

    // persistence tracking — set per session/round
    static GameSessionEntity currentSession = null;
    static int currentRoundNumber = 0;

    public static void main(String[] args) {
        int bots = 3;
        int games = 1;
        boolean human = false;
        boolean showStats = false;
        int targetScore = 0; // 0 = disabled; use --games count instead
        long seed = System.currentTimeMillis();

        for (int i = 0; i < args.length; i++) {
            if (args[i].equals("--bots") && i + 1 < args.length) {
                bots = Integer.parseInt(args[++i]);
            } else if (args[i].equals("--games") && i + 1 < args.length) {
                games = Integer.parseInt(args[++i]);
            } else if (args[i].equals("--target") && i + 1 < args.length) {
                targetScore = Integer.parseInt(args[++i]);
            } else if (args[i].equals("--human")) {
                human = true;
            } else if (args[i].equals("--quiet")) {
                quiet = true;
            } else if (args[i].equals("--seed") && i + 1 < args.length) {
                seed = Long.parseLong(args[++i]);
            } else if (args[i].equals("--stats")) {
                showStats = true;
            } else if (args[i].equals("--self-test")) {
                selfTest();
                return;
            } else if (args[i].equals("--help")) {
                System.out.println("Usage: scripts/run.sh [--bots N] [--games N] [--target N] [--human] [--quiet] [--seed N] [--stats]");
                return;
            }
        }

        // suppress verbose Hibernate startup noise so the CLI stays readable
        java.util.logging.Logger.getLogger("org.hibernate").setLevel(java.util.logging.Level.WARNING);
        PersistenceService.init("uno-pu");

        if (showStats) {
            PersistenceService.printStats();
            PersistenceService.close();
            return;
        }

        state.random = new Random(seed);
        setupPlayers(bots, human);

        if (state.players.size() < 2 || state.players.size() > 4) {
            System.out.println("UNO needs 2 to 4 players.");
            PersistenceService.close();
            return;
        }

        currentSession = PersistenceService.startSession(state.players);

        if (targetScore > 0) {
            // multi-round game: keep playing rounds until someone reaches the target score
            int g = 0;
            int safety = 0;
            while (!hasReachedTarget(targetScore) && safety < 10000) {
                safety++;
                g++;
                currentRoundNumber = g;
                Display.gameStart(g);
                GameLog.gameStart(g, state.players.size());
                playGame();
            }
            Display.targetReached(targetScore);
            Display.finalScores(state.players, state.scores);
            Display.finalWinner(finalWinnerName());
        } else {
            for (int g = 1; g <= games; g++) {
                currentRoundNumber = g;
                Display.gameStart(g);
                GameLog.gameStart(g, state.players.size());
                playGame();
            }
            Display.finalScores(state.players, state.scores);
        }

        PersistenceService.finishSession(currentSession, state.players, state.scores);
        GameLog.gameEnd();
        PersistenceService.close();
    }

    // true when at least one player has reached (or passed) the target score
    static boolean hasReachedTarget(int target) {
        for (int s : state.scores) {
            if (s >= target) return true;
        }
        return false;
    }

    // player with the highest score; ties resolve to the first player found with that score
    static String finalWinnerName() {
        int bestIndex = -1;
        int bestScore = Integer.MIN_VALUE;
        for (int i = 0; i < state.players.size(); i++) {
            if (state.scores[i] > bestScore) {
                bestScore = state.scores[i];
                bestIndex = i;
            }
        }
        return bestIndex >= 0 ? state.players.get(bestIndex).name : "";
    }

    static void setupPlayers(int bots, boolean human) {
        state.players.clear();
        if (human) {
            state.players.add(new Player("You", true));
        }
        for (int i = 1; i <= bots; i++) {
            state.players.add(new Player("Bot" + i, false));
        }
    }

    static void playGame() {
        buildDeck();
        Collections.shuffle(state.deck, state.random);
        state.discard.clear();
        dealHands();
        state.upCard = draw();
        while (state.upCard.startsWith("W")) {
            state.discard.add(state.upCard);
            state.upCard = draw();
        }
        state.calledColor = "";
        state.direction = 1;
        state.currentPlayer = state.random.nextInt(state.players.size());

        int guard = 0;
        while (guard < 3000) {
            guard++;
            Player current = state.players.get(state.currentPlayer);
            checkUnoPenalty(current);

            Display.turnState(state.upCard, state.calledColor, current.name, current.hand);
            GameLog.playerTurn(current.name, state.upCard, state.calledColor);

            int chosen = -1;
            if (current.isHuman) {
                chosen = askHuman(current.hand);
            } else {
                chosen = chooseBotCard(current.hand);
            }

            if (chosen == -1) {
                chosen = handleDraw(current.hand, current.name);
            }

            if (chosen >= 0) {
                if (chosen >= current.hand.size()) {
                    Display.penaltyCard(current.name);
                    current.hand.add(draw());
                    next();
                    continue;
                }

                String card = current.hand.get(chosen);

                if (!isLegal(card, state.upCard, state.calledColor)) {
                    Display.illegalCard(current.name, card);
                    current.hand.add(draw());
                    next();
                    continue;
                }

                current.hand.remove(chosen);
                state.discard.add(state.upCard);
                state.upCard = card;
                state.calledColor = "";
                Display.playerPlays(current.name, card);
                GameLog.cardPlayed(current.name, card);

                if (card.equals("W") || card.equals("W4")) {
                    if (current.isHuman) {
                        state.calledColor = askColor();
                    } else {
                        state.calledColor = chooseBotColor(current.hand);
                    }
                    Display.playerCallsColor(current.name, state.calledColor);
                }

                if (current.hand.size() == 1) {
                    Display.uno(current.name);
                    if (current.isHuman) {
                        current.saidUno = askUnoCall();
                    } else {
                        current.saidUno = true; // bots always call it (documented simplification)
                    }
                }

                if (current.hand.size() == 0) {
                    scoreRound(current.name);
                    return;
                }

                applyCardEffect(card);
            } else {
                next();
            }
        }
        Display.safetyLimit();
    }

    // draws a card for the current player and returns the index to play it,
    // or -1 if the drawn card isn't legal (or human chose not to play it)
    static int handleDraw(ArrayList<String> hand, String name) {
        String drawn = draw();
        hand.add(drawn);
        Display.playerDraws(name, drawn);
        GameLog.cardDrawn(name, drawn);
        if (isLegal(drawn, state.upCard, state.calledColor)) {
            if (!state.players.get(state.currentPlayer).isHuman) {
                return hand.size() - 1;
            } else {
                System.out.print("Play drawn card " + drawn + "? y/n: ");
                String answer = scanner.nextLine();
                if (answer.equalsIgnoreCase("y") || answer.equalsIgnoreCase("yes")) {
                    return hand.size() - 1;
                }
            }
        }
        return -1;
    }

    static void dealHands() {
        for (int i = 0; i < state.players.size(); i++) {
            state.players.get(i).hand.clear();
            state.players.get(i).saidUno = false;
            for (int j = 0; j < 7; j++) {
                state.players.get(i).hand.add(draw());
            }
        }
    }

    static void buildDeck() {
        state.deck.clear();
        String[] colors = {"R", "Y", "G", "B"};
        for (int c = 0; c < colors.length; c++) {
            state.deck.add(colors[c] + "0");
            for (int n = 1; n <= 9; n++) {
                state.deck.add(colors[c] + n);
                state.deck.add(colors[c] + n);
            }
            state.deck.add(colors[c] + "S");
            state.deck.add(colors[c] + "S");
            state.deck.add(colors[c] + "R");
            state.deck.add(colors[c] + "R");
            state.deck.add(colors[c] + "+2");
            state.deck.add(colors[c] + "+2");
        }
        for (int i = 0; i < 4; i++) {
            state.deck.add("W");
            state.deck.add("W4");
        }
    }

    static String draw() {
        if (state.deck.size() == 0) {
            state.deck.addAll(state.discard);
            state.discard.clear();
            Collections.shuffle(state.deck, state.random);
        }
        if (state.deck.size() == 0) {
            return "W";
        }
        return state.deck.remove(0);
    }

    // checks if the player is sitting at 1 card without having called UNO,
    // and applies the missed-call penalty (draw 2) at the start of their turn
    static void checkUnoPenalty(Player p) {
        if (p.hand.size() == 1 && !p.saidUno) {
            p.hand.add(draw());
            p.hand.add(draw());
            Display.missedUnoPenalty(p.name);
            GameLog.unoPenalty(p.name);
            p.saidUno = false;
        }
    }

    static boolean askUnoCall() {
        System.out.print("Call UNO? y/n: ");
        String input = scanner.nextLine().trim();
        return input.equalsIgnoreCase("y") || input.equalsIgnoreCase("yes") || input.equalsIgnoreCase("uno");
    }

    static void scoreRound(String winnerName) {
        int points = 0;
        for (int i = 0; i < state.players.size(); i++) {
            if (i != state.currentPlayer) {
                for (int j = 0; j < state.players.get(i).hand.size(); j++) {
                    points += points(state.players.get(i).hand.get(j));
                }
            }
        }
        state.scores[state.currentPlayer] += points;
        Display.winsRound(winnerName, points);
        GameLog.roundEnd(winnerName, points);
        if (currentSession != null) {
            PersistenceService.addRound(currentSession, currentRoundNumber, winnerName, points);
        }
    }

    static void applyCardEffect(String card) {
        switch (rank(card)) {
            case "SKIP":
                next();
                next();
                break;
            case "REVERSE":
                state.direction = state.direction * -1;
                if (state.players.size() == 2) {
                    next();
                    next();
                } else {
                    next();
                }
                break;
            case "DRAW_TWO":
                next();
                state.players.get(state.currentPlayer).hand.add(draw());
                state.players.get(state.currentPlayer).hand.add(draw());
                Display.drawsTwo(state.players.get(state.currentPlayer).name);
                next();
                break;
            case "WILD_DRAW_FOUR":
                next();
                for (int i = 0; i < 4; i++) {
                    state.players.get(state.currentPlayer).hand.add(draw());
                }
                Display.drawsFour(state.players.get(state.currentPlayer).name);
                next();
                break;
            default:
                next();
                break;
        }
    }

    static int chooseBotCard(ArrayList<String> hand) {
        for (int i = 0; i < hand.size(); i++) {
            if (rank(hand.get(i)).equals("DRAW_TWO") && isLegal(hand.get(i), state.upCard, state.calledColor)) {
                return i;
            }
        }
        for (int i = 0; i < hand.size(); i++) {
            if (rank(hand.get(i)).equals("SKIP") && isLegal(hand.get(i), state.upCard, state.calledColor)) {
                return i;
            }
        }
        for (int i = 0; i < hand.size(); i++) {
            if (rank(hand.get(i)).equals("NUMBER") && isLegal(hand.get(i), state.upCard, state.calledColor)) {
                return i;
            }
        }
        for (int i = 0; i < hand.size(); i++) {
            if (hand.get(i).startsWith("W")) {
                return i;
            }
        }
        return -1;
    }

    // just parsing — no legality check here, returns -1 for draw, -2 if not understood
    static int parseCardInput(String input, ArrayList<String> hand) {
        if (input.equals("DRAW")) return -1;
        try {
            int index = Integer.parseInt(input);
            if (index >= 0 && index < hand.size()) return index;
        } catch (Exception ignored) {
        }
        for (int i = 0; i < hand.size(); i++) {
            if (hand.get(i).equals(input)) return i;
        }
        return -2;
    }

    static int askHuman(ArrayList<String> hand) {
        while (true) {
            System.out.print("Choose card index/code or draw: ");
            String input = scanner.nextLine().trim().toUpperCase();
            int idx = parseCardInput(input, hand);
            if (idx == -1) return -1;
            if (idx == -2) {
                System.out.println("Card not found.");
                GameLog.invalidInput("You", "card-not-found:" + input);
                continue;
            }
            if (!isLegal(hand.get(idx), state.upCard, state.calledColor)) {
                System.out.println("That card is not legal.");
                GameLog.invalidInput("You", "illegal-card:" + hand.get(idx));
                continue;
            }
            return idx;
        }
    }

    static String askColor() {
        while (true) {
            System.out.print("Call color R/Y/G/B: ");
            String input = scanner.nextLine().trim().toUpperCase();
            if (input.equals("R")) return "R";
            if (input.equals("Y")) return "Y";
            if (input.equals("G")) return "G";
            if (input.equals("B")) return "B";
            System.out.println("Bad color.");
        }
    }

    static String chooseBotColor(ArrayList<String> hand) {
        int r = 0, y = 0, g = 0, b = 0;
        for (int i = 0; i < hand.size(); i++) {
            String c = color(hand.get(i));
            if (c.equals("R")) r++;
            else if (c.equals("Y")) y++;
            else if (c.equals("G")) g++;
            else if (c.equals("B")) b++;
        }
        if (r >= y && r >= g && r >= b) return "R";
        if (y >= r && y >= g && y >= b) return "Y";
        if (g >= r && g >= y && g >= b) return "G";
        return "B";
    }

    // quick helpers so i don't have to write new Card(...) everywhere
    static boolean isLegal(String card, String up, String call) { return new Card(card).isLegalOn(up, call); }
    static String color(String card)  { return new Card(card).color(); }
    static String rank(String card)   { return new Card(card).rank(); }
    static int    number(String card) { return new Card(card).number(); }
    static int    points(String card) { return new Card(card).points(); }

    static void next() {
        state.currentPlayer += state.direction;
        if (state.currentPlayer >= state.players.size()) state.currentPlayer = 0;
        if (state.currentPlayer < 0) state.currentPlayer = state.players.size() - 1;
    }

    static String join(ArrayList<String> cards) {
        String out = "";
        for (int i = 0; i < cards.size(); i++) {
            out += i + ":" + cards.get(i);
            if (i < cards.size() - 1) out += " ";
        }
        return out;
    }

    static void selfTest() {
        int passed = 0;
        if (color("R5").equals("R")) passed++; else fail("color R5");
        if (rank("G+2").equals("DRAW_TWO")) passed++; else fail("rank +2");
        if (points("W4") == 50) passed++; else fail("wild points");
        if (isLegal("R2", "R9", "")) passed++; else fail("same color");
        if (isLegal("G9", "R9", "")) passed++; else fail("same number");
        if (isLegal("B3", "W", "B")) passed++; else fail("called color");
        if (!isLegal("B3", "R9", "")) passed++; else fail("illegal mismatch");

        ArrayList<String> h = new ArrayList<>();
        h.add("B3"); h.add("R4"); h.add("W");
        state.upCard = "R9";
        state.calledColor = "";
        if (chooseBotCard(h) == 1) passed++; else fail("bot normal before wild");

        ArrayList<String> h2 = new ArrayList<>();
        h2.add("B1"); h2.add("B2"); h2.add("R3");
        if (chooseBotColor(h2).equals("B")) passed++; else fail("bot color");

        System.out.println("Passed " + passed + " characterization checks.");
    }

    static void fail(String name) {
        throw new RuntimeException("Failed: " + name);
    }
}

import java.util.ArrayList;

// holds everything about one player: name, human or bot, and their cards
class Player {
    String name;
    boolean isHuman;
    ArrayList<String> hand = new ArrayList<>();

    Player(String name, boolean isHuman) {
        this.name = name;
        this.isHuman = isHuman;
    }
}

import java.util.ArrayList;

// holds everything about one player: name, human or bot, and their cards
class Player {
    String name;
    boolean isHuman;
    ArrayList<String> hand = new ArrayList<>();
    // tracks whether this player has called "UNO" since last reaching 1 card
    boolean saidUno = false;

    Player(String name, boolean isHuman) {
        this.name = name;
        this.isHuman = isHuman;
    }
}

import java.util.ArrayList;

// Characterization tests - these pin down what the code actually does right now,
// before I start refactoring. Not testing ideal UNO, testing THIS code.
// Run: java -cp out CharacterizationTest
public class CharacterizationTest {

    static int passed = 0;
    static int failed = 0;
    static int total  = 0;

    // p.s i havent used testng or junit. i wrote this testing with pure java
    public static void main(String[] args) {
        System.out.println("=== Characterization Tests ===\n");

        suite("color()",          CharacterizationTest::testColor);
        suite("rank()",           CharacterizationTest::testRank);
        suite("number()",         CharacterizationTest::testNumber);
        suite("points()",         CharacterizationTest::testPoints);
        suite("isLegal – color",  CharacterizationTest::testIsLegalByColor);
        suite("isLegal – number", CharacterizationTest::testIsLegalByNumber);
        suite("isLegal – action", CharacterizationTest::testIsLegalByAction);
        suite("isLegal – wild",   CharacterizationTest::testIsLegalWild);
        suite("isLegal – called color", CharacterizationTest::testIsLegalCalledColor);
        suite("isLegal – illegal combos", CharacterizationTest::testIsLegalIllegal);
        suite("Bot card priority: DRAW_TWO first", CharacterizationTest::testBotPrefersDraw2);
        suite("Bot card priority: SKIP second",    CharacterizationTest::testBotPrefersSkip);
        suite("Bot card priority: NUMBER before WILD", CharacterizationTest::testBotPrefersNumberBeforeWild);
        suite("Bot plays WILD when only option",   CharacterizationTest::testBotPlayWildWhenOnly);
        suite("Bot returns -1 when no legal card", CharacterizationTest::testBotReturnsMinusOne);
        suite("Bot color: picks most in hand",     CharacterizationTest::testBotColorMajority);
        suite("Bot color: tie breaks to first max",CharacterizationTest::testBotColorTie);
        suite("Scoring – numbers",                 CharacterizationTest::testScoringNumbers);
        suite("Scoring – action cards",            CharacterizationTest::testScoringActions);
        suite("Scoring – wilds",                   CharacterizationTest::testScoringWilds);
        suite("Edge: illegal input index behavior",CharacterizationTest::testIllegalIndexBehavior);
        suite("Edge: empty drawn card play check", CharacterizationTest::testDrawnCardLegalCheck);
        suite("Edge: reverse on 2-player acts like skip", CharacterizationTest::testReverse2Player);
        suite("Edge: draw from empty deck recycles discard", CharacterizationTest::testDeckRecycle);
        suite("Effect: skip actually skips next player", CharacterizationTest::testSkipEffect);
        suite("Effect: reverse changes direction", CharacterizationTest::testReverseEffect);
        suite("Effect: draw two adds 2 cards to next player", CharacterizationTest::testDrawTwoEffect);

        System.out.println("\n==============================");
        System.out.printf("TOTAL: %d passed, %d failed out of %d%n", passed, failed, total);
        System.out.println("==============================");

        if (failed > 0) {
            System.exit(1);
        }
    }

    // color() just reads the first character
    static void testColor() {
        check("R5 → R",  Main.color("R5").equals("R"));
        check("Y0 → Y",  Main.color("Y0").equals("Y"));
        check("GS → G",  Main.color("GS").equals("G"));
        check("BR → B",  Main.color("BR").equals("B"));
        check("W  → ''", Main.color("W").equals(""));
        check("W4 → ''", Main.color("W4").equals(""));
        check("B+2 → B", Main.color("B+2").equals("B"));
    }

    // rank() looks at the suffix
    static void testRank() {
        check("W  → WILD",           Main.rank("W").equals("WILD"));
        check("W4 → WILD_DRAW_FOUR", Main.rank("W4").equals("WILD_DRAW_FOUR"));
        check("RS → SKIP",           Main.rank("RS").equals("SKIP"));
        check("GS → SKIP",           Main.rank("GS").equals("SKIP"));
        check("YR → REVERSE",        Main.rank("YR").equals("REVERSE"));
        check("BR → REVERSE",        Main.rank("BR").equals("REVERSE"));
        check("R+2 → DRAW_TWO",      Main.rank("R+2").equals("DRAW_TWO"));
        check("G+2 → DRAW_TWO",      Main.rank("G+2").equals("DRAW_TWO"));
        check("R5 → NUMBER",         Main.rank("R5").equals("NUMBER"));
        check("B0 → NUMBER",         Main.rank("B0").equals("NUMBER"));
        check("Y9 → NUMBER",         Main.rank("Y9").equals("NUMBER"));
    }

    // number() returns -1 for anything that isn't a number card
    static void testNumber() {
        check("R0 → 0", Main.number("R0") == 0);
        check("G7 → 7", Main.number("G7") == 7);
        check("Y9 → 9", Main.number("Y9") == 9);
        check("B1 → 1", Main.number("B1") == 1);
        check("RS → -1",  Main.number("RS") == -1);
        check("W  → -1",  Main.number("W")  == -1);
        check("W4 → -1",  Main.number("W4") == -1);
    }

    static void testPoints() {
        check("R0  → 0",  Main.points("R0")  == 0);
        check("G7  → 7",  Main.points("G7")  == 7);
        check("Y9  → 9",  Main.points("Y9")  == 9);
        check("RS  → 20", Main.points("RS")  == 20);
        check("YR  → 20", Main.points("YR")  == 20);
        check("B+2 → 20", Main.points("B+2") == 20);
        check("W   → 50", Main.points("W")   == 50);
        check("W4  → 50", Main.points("W4")  == 50);
    }

    static void testIsLegalByColor() {
        check("R2 on R9 (same color)",  Main.isLegal("R2",  "R9",  ""));
        check("RS on R5 (same color)",  Main.isLegal("RS",  "R5",  ""));
        check("R+2 on RR (same color)", Main.isLegal("R+2", "RR",  ""));
        check("R0 on R0 (same color)",  Main.isLegal("R0",  "R0",  ""));
        check("YS on YR (same color)",  Main.isLegal("YS",  "YR",  ""));
    }

    static void testIsLegalByNumber() {
        check("G9 on R9 (same number, diff color)", Main.isLegal("G9", "R9", ""));
        check("B5 on Y5 (same number)",             Main.isLegal("B5", "Y5", ""));
        check("R0 on G0 (same number 0)",           Main.isLegal("R0", "G0", ""));
        check("G3 on R9 (diff color+number) illegal", !Main.isLegal("G3", "R9", ""));
    }

    static void testIsLegalByAction() {
        check("RS on GS (skip matches skip)",           Main.isLegal("RS",  "GS",  ""));
        check("YR on BR (reverse matches reverse)",     Main.isLegal("YR",  "BR",  ""));
        check("B+2 on G+2 (draw two matches draw two)", Main.isLegal("B+2", "G+2", ""));
        check("RS on G+2 (skip vs draw2) illegal", !Main.isLegal("RS", "G+2", ""));
    }

    // wilds are always playable
    static void testIsLegalWild() {
        check("W on R5",   Main.isLegal("W",  "R5",  ""));
        check("W on BS",   Main.isLegal("W",  "BS",  ""));
        check("W4 on G3",  Main.isLegal("W4", "G3",  ""));
        check("W4 on YR",  Main.isLegal("W4", "YR",  ""));
        check("W on W (called R)", Main.isLegal("W",  "W",  "R"));
        check("W4 on W4 (called B)", Main.isLegal("W4", "W4", "B"));
    }

    // after a wild is played the called color is what matters, not the card's color
    static void testIsLegalCalledColor() {
        check("R3 on W, called R → legal",  Main.isLegal("R3",  "W", "R"));
        check("RS on W, called R → legal",  Main.isLegal("RS",  "W", "R"));
        check("B3 on W, called R → illegal",!Main.isLegal("B3",  "W", "R"));
        check("G9 on W, called R → illegal",!Main.isLegal("G9",  "W", "R"));
        check("W on W, called R → legal",   Main.isLegal("W",   "W", "R"));
        check("W4 on W, called B → legal",  Main.isLegal("W4",  "W", "B"));
    }

    static void testIsLegalIllegal() {
        check("B3 on R9 (color+number mismatch)",    !Main.isLegal("B3",  "R9",  ""));
        check("GS on R9 (color mismatch, diff rank)", !Main.isLegal("GS",  "R9",  ""));
        check("Y+2 on RS (action mismatch)",          !Main.isLegal("Y+2", "RS",  ""));
    }

    // bot prefers DRAW_TWO > SKIP > NUMBER > WILD (hardcoded priority passes)
    static void testBotPrefersDraw2() {
        GameState saved = Main.state;
        Main.state = new GameState();
        Main.state.upCard = "R9";
        Main.state.calledColor = "";
        ArrayList<String> hand = hand("R5", "R+2", "RS", "W");
        int idx = Main.chooseBotCard(hand);
        check("bot picks R+2 (DRAW_TWO) first", hand.get(idx).equals("R+2"));
        Main.state = saved;
    }

    static void testBotPrefersSkip() {
        GameState saved = Main.state;
        Main.state = new GameState();
        Main.state.upCard = "R9";
        Main.state.calledColor = "";
        ArrayList<String> hand = hand("R5", "RS", "W");
        int idx = Main.chooseBotCard(hand);
        check("bot picks RS (SKIP) before R5 or W", hand.get(idx).equals("RS"));
        Main.state = saved;
    }

    static void testBotPrefersNumberBeforeWild() {
        GameState saved = Main.state;
        Main.state = new GameState();
        Main.state.upCard = "R9";
        Main.state.calledColor = "";
        ArrayList<String> hand = hand("B3", "R5", "W");
        int idx = Main.chooseBotCard(hand);
        check("bot picks R5 (NUMBER) before W", hand.get(idx).equals("R5"));
        Main.state = saved;
    }

    static void testBotPlayWildWhenOnly() {
        GameState saved = Main.state;
        Main.state = new GameState();
        Main.state.upCard = "R9";
        Main.state.calledColor = "";
        ArrayList<String> hand = hand("B3", "G2", "W");
        int idx = Main.chooseBotCard(hand);
        check("bot plays W when it's the only legal card", hand.get(idx).equals("W"));
        Main.state = saved;
    }

    static void testBotReturnsMinusOne() {
        GameState saved = Main.state;
        Main.state = new GameState();
        Main.state.upCard = "R9";
        Main.state.calledColor = "";
        ArrayList<String> hand = hand("B3", "G2", "YS");
        int idx = Main.chooseBotCard(hand);
        check("bot returns -1 when no legal card", idx == -1);
        Main.state = saved;
    }

    static void testBotColorMajority() {
        ArrayList<String> hand = hand("B1", "B2", "B3", "R5", "G7");
        check("bot picks B (3 vs 1 vs 1)", Main.chooseBotColor(hand).equals("B"));
    }

    // noticed that when two colors tie, R wins because it's checked first in the if-chain
    static void testBotColorTie() {
        ArrayList<String> hand = hand("R1", "R2", "B3", "B4");
        String color = Main.chooseBotColor(hand);
        check("bot picks R when R and B tied (current behavior)", color.equals("R"));
    }

    static void testScoringNumbers() {
        check("R0 = 0 pts",  Main.points("R0") == 0);
        check("Y1 = 1 pt",   Main.points("Y1") == 1);
        check("G5 = 5 pts",  Main.points("G5") == 5);
        check("B9 = 9 pts",  Main.points("B9") == 9);
    }

    static void testScoringActions() {
        check("RS  = 20 pts", Main.points("RS")  == 20);
        check("GR  = 20 pts", Main.points("GR")  == 20);
        check("Y+2 = 20 pts", Main.points("Y+2") == 20);
    }

    static void testScoringWilds() {
        check("W  = 50 pts", Main.points("W")  == 50);
        check("W4 = 50 pts", Main.points("W4") == 50);
    }

    // found this while testing: if you pass a single color letter like "Y",
    // rank() falls through to NUMBER and then parseInt("") blows up.
    // the game never does this in practice but it's a fragile spot worth noting.
    static void testIllegalIndexBehavior() {
        check("empty string color is ''", Main.color("").equals(""));
        check("color of 'W5' is ''", Main.color("W5").equals(""));

        boolean threw = false;
        try {
            Main.number("Y"); // rank("Y") = NUMBER, parseInt("") = crash
        } catch (NumberFormatException e) {
            threw = true;
        }
        check("number('Y') throws NumberFormatException", threw);
    }

    // drawn card is checked with isLegal too — bot auto-plays if legal, human gets asked
    static void testDrawnCardLegalCheck() {
        check("drawn R5 is legal on R9", Main.isLegal("R5", "R9", ""));
        check("drawn B3 is not legal on R9", !Main.isLegal("B3", "R9", ""));
    }

    // reverse flips direction; on 2 players next() is called twice so it skips like a skip
    static void testReverse2Player() {
        GameState saved = Main.state;
        Main.state = new GameState();
        Main.state.direction = 1;
        Main.state.direction = Main.state.direction * -1;
        check("direction flips from 1 to -1", Main.state.direction == -1);
        Main.state.direction = Main.state.direction * -1;
        check("direction flips back to 1", Main.state.direction == 1);
        Main.state = saved;
    }

    // when the deck runs out, discard gets reshuffled back in
    static void testDeckRecycle() {
        GameState saved = Main.state;
        Main.state = new GameState();
        Main.state.discard.add("R5");
        Main.state.discard.add("G3");

        String drawn = Main.draw();
        check("can draw from recycled discard", drawn != null && !drawn.isEmpty());
        check("discard is cleared after recycle", Main.state.discard.size() == 0);
        Main.state = saved;
    }

    // skip calls next() twice so player 1 gets completely skipped
    static void testSkipEffect() {
        GameState saved = Main.state;
        Main.state = new GameState();
        Main.state.players.add(new Player("A", false));
        Main.state.players.add(new Player("B", false));
        Main.state.players.add(new Player("C", false));
        Main.state.currentPlayer = 0;
        Main.state.direction = 1;
        Main.next();
        Main.next();
        check("skip: player 0 plays, player 1 skipped, lands on 2", Main.state.currentPlayer == 2);
        Main.state = saved;
    }

    // reverse flips direction; with 3 players moving backwards from 1 lands on 0
    static void testReverseEffect() {
        GameState saved = Main.state;
        Main.state = new GameState();
        Main.state.players.add(new Player("A", false));
        Main.state.players.add(new Player("B", false));
        Main.state.players.add(new Player("C", false));
        Main.state.currentPlayer = 1;
        Main.state.direction = 1;
        Main.state.direction = Main.state.direction * -1;
        Main.next();
        check("reverse: direction is now -1", Main.state.direction == -1);
        check("reverse: next player is 0 (moved backwards from 1)", Main.state.currentPlayer == 0);
        Main.state = saved;
    }

    // draw two: next player gets 2 extra cards and their turn is skipped
    static void testDrawTwoEffect() {
        GameState saved = Main.state;
        Main.state = new GameState();
        Main.state.players.add(new Player("A", false));
        Main.state.players.add(new Player("B", false));
        Main.state.direction = 1;
        Main.state.currentPlayer = 0;
        Main.state.deck.add("R1");
        Main.state.deck.add("G3");
        Main.state.deck.add("B5");

        int before = Main.state.players.get(1).hand.size();

        // mirrors exactly what the game loop does for DRAW_TWO
        Main.next();
        Main.state.players.get(Main.state.currentPlayer).hand.add(Main.draw());
        Main.state.players.get(Main.state.currentPlayer).hand.add(Main.draw());
        Main.next();

        check("draw two: player 1 got 2 cards", Main.state.players.get(1).hand.size() == before + 2);
        check("draw two: ends back at player 0 (B's turn skipped)", Main.state.currentPlayer == 0);
        Main.state = saved;
    }

    static ArrayList<String> hand(String... cards) {
        ArrayList<String> h = new ArrayList<>();
        for (String c : cards) h.add(c);
        return h;
    }

    @FunctionalInterface
    interface TestBlock { void run(); }

    static void suite(String name, TestBlock block) {
        System.out.println("  [" + name + "]");
        block.run();
        System.out.println();
    }

    static void check(String description, boolean condition) {
        total++;
        if (condition) {
            System.out.println("    PASS  " + description);
            passed++;
        } else {
            System.out.println("    FAIL  " + description);
            failed++;
        }
    }
}

import java.util.ArrayList;

// Characterization tests - these pin down what the code actually does right now,
// before I start refactoring. Not testing ideal UNO, testing THIS code.
// Run: java -cp out CharacterizationTest
public class CharacterizationTest {

    static int passed = 0;
    static int failed = 0;
    static int total  = 0;

    // p.s i havent used testng or junit. i wrote this testing with pure java
    public static void main(String[] args) {
        System.out.println("=== Characterization Tests ===\n");

        suite("color()",          CharacterizationTest::testColor);
        suite("rank()",           CharacterizationTest::testRank);
        suite("number()",         CharacterizationTest::testNumber);
        suite("points()",         CharacterizationTest::testPoints);
        suite("isLegal – color",  CharacterizationTest::testIsLegalByColor);
        suite("isLegal – number", CharacterizationTest::testIsLegalByNumber);
        suite("isLegal – action", CharacterizationTest::testIsLegalByAction);
        suite("isLegal – wild",   CharacterizationTest::testIsLegalWild);
        suite("isLegal – called color", CharacterizationTest::testIsLegalCalledColor);
        suite("isLegal – illegal combos", CharacterizationTest::testIsLegalIllegal);
        suite("Bot card priority: DRAW_TWO first", CharacterizationTest::testBotPrefersDraw2);
        suite("Bot card priority: SKIP second",    CharacterizationTest::testBotPrefersSkip);
        suite("Bot card priority: NUMBER before WILD", CharacterizationTest::testBotPrefersNumberBeforeWild);
        suite("Bot plays WILD when only option",   CharacterizationTest::testBotPlayWildWhenOnly);
        suite("Bot returns -1 when no legal card", CharacterizationTest::testBotReturnsMinusOne);
        suite("Bot color: picks most in hand",     CharacterizationTest::testBotColorMajority);
        suite("Bot color: tie breaks to first max",CharacterizationTest::testBotColorTie);
        suite("Scoring – numbers",                 CharacterizationTest::testScoringNumbers);
        suite("Scoring – action cards",            CharacterizationTest::testScoringActions);
        suite("Scoring – wilds",                   CharacterizationTest::testScoringWilds);
        suite("Edge: illegal input index behavior",CharacterizationTest::testIllegalIndexBehavior);
        suite("Edge: empty drawn card play check", CharacterizationTest::testDrawnCardLegalCheck);
        suite("Edge: reverse on 2-player acts like skip", CharacterizationTest::testReverse2Player);
        suite("Edge: draw from empty deck recycles discard", CharacterizationTest::testDeckRecycle);
        suite("Effect: skip actually skips next player", CharacterizationTest::testSkipEffect);
        suite("Effect: reverse changes direction", CharacterizationTest::testReverseEffect);
        suite("Effect: draw two adds 2 cards to next player", CharacterizationTest::testDrawTwoEffect);
        suite("Effect: wild draw four adds 4 cards and skips", CharacterizationTest::testWildDrawFourEffect);
        suite("UNO: penalty applied when not called", CharacterizationTest::testUnoPenaltyApplied);
        suite("UNO: no penalty when called", CharacterizationTest::testUnoPenaltyNotAppliedWhenCalled);
        suite("UNO: no penalty when hand size != 1", CharacterizationTest::testUnoPenaltyIgnoredAboveOneCard);
        suite("Target score: detects when a player reaches it", CharacterizationTest::testHasReachedTarget);
        suite("Target score: picks highest-scoring player as winner", CharacterizationTest::testFinalWinnerName);

        System.out.println("\n==============================");
        System.out.printf("TOTAL: %d passed, %d failed out of %d%n", passed, failed, total);
        System.out.println("==============================");

        if (failed > 0) {
            System.exit(1);
        }
    }

    // color() just reads the first character
    static void testColor() {
        check("R5 → R",  Main.color("R5").equals("R"));
        check("Y0 → Y",  Main.color("Y0").equals("Y"));
        check("GS → G",  Main.color("GS").equals("G"));
        check("BR → B",  Main.color("BR").equals("B"));
        check("W  → ''", Main.color("W").equals(""));
        check("W4 → ''", Main.color("W4").equals(""));
        check("B+2 → B", Main.color("B+2").equals("B"));
    }

    // rank() looks at the suffix
    static void testRank() {
        check("W  → WILD",           Main.rank("W").equals("WILD"));
        check("W4 → WILD_DRAW_FOUR", Main.rank("W4").equals("WILD_DRAW_FOUR"));
        check("RS → SKIP",           Main.rank("RS").equals("SKIP"));
        check("GS → SKIP",           Main.rank("GS").equals("SKIP"));
        check("YR → REVERSE",        Main.rank("YR").equals("REVERSE"));
        check("BR → REVERSE",        Main.rank("BR").equals("REVERSE"));
        check("R+2 → DRAW_TWO",      Main.rank("R+2").equals("DRAW_TWO"));
        check("G+2 → DRAW_TWO",      Main.rank("G+2").equals("DRAW_TWO"));
        check("R5 → NUMBER",         Main.rank("R5").equals("NUMBER"));
        check("B0 → NUMBER",         Main.rank("B0").equals("NUMBER"));
        check("Y9 → NUMBER",         Main.rank("Y9").equals("NUMBER"));
    }

    // number() returns -1 for anything that isn't a number card
    static void testNumber() {
        check("R0 → 0", Main.number("R0") == 0);
        check("G7 → 7", Main.number("G7") == 7);
        check("Y9 → 9", Main.number("Y9") == 9);
        check("B1 → 1", Main.number("B1") == 1);
        check("RS → -1",  Main.number("RS") == -1);
        check("W  → -1",  Main.number("W")  == -1);
        check("W4 → -1",  Main.number("W4") == -1);
    }

    static void testPoints() {
        check("R0  → 0",  Main.points("R0")  == 0);
        check("G7  → 7",  Main.points("G7")  == 7);
        check("Y9  → 9",  Main.points("Y9")  == 9);
        check("RS  → 20", Main.points("RS")  == 20);
        check("YR  → 20", Main.points("YR")  == 20);
        check("B+2 → 20", Main.points("B+2") == 20);
